fn solve(input: Vec<i8>) -> Vec<&'static str> {
    // Helper to check if n is a power of two (assuming n > 0)
    fn is_power_of_two(n: i32) -> bool {
        (n & (n - 1)) == 0
    }

    // "limited-prime" check as defined:
    // p ≤ 1 => not prime
    // p = 2 => prime
    // even p > 2 => not prime
    // odd p > 2 => prime
    fn is_limited_prime(p: i32) -> bool {
        if p <= 1 {
            false
        } else if p == 2 {
            true
        } else if p % 2 == 0 {
            false
        } else {
            true
        }
    }

    // Extract number of test cases t (first element) as i32 for safe arithmetic.
    let t = input[0] as usize;
    let mut results = Vec::with_capacity(t);

    for &val in &input[1..=t] {
        // Convert to i32 to safely handle arithmetic and modulo
        let n = val as i32;

        let winner = if n == 1 {
            "FastestFinger"
        } else if n == 2 {
            "Ashishgup"
        } else if is_power_of_two(n) {
            // power of two excluding n=2 is caught here --> FastestFinger
            "FastestFinger"
        } else if n % 4 != 2 {
            // all odd and multiples of 4 fall here --> Ashishgup
            "Ashishgup"
        } else {
            // n % 4 == 2 case
            let p = n / 2;
            if is_limited_prime(p) {
                "FastestFinger"
            } else {
                "Ashishgup"
            }
        };

        results.push(winner);
    }

    results
}